-- University Course Management API: схема + тестовые данные (PostgreSQL)
-- Приложение и так создаёт БД автоматически (EnsureCreated + DbSeeder).
-- Этот скрипт — альтернатива/дамп для сдачи. Запускать на ПУСТОЙ базе university_db.

CREATE TABLE "Teachers" (
    "Id"         integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FirstName"  varchar(100) NOT NULL,
    "LastName"   varchar(100) NOT NULL,
    "Email"      varchar(200) NOT NULL,
    "Department" varchar(150) NOT NULL
);
CREATE UNIQUE INDEX "IX_Teachers_Email" ON "Teachers" ("Email");

CREATE TABLE "Students" (
    "Id"        integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "FirstName" varchar(100) NOT NULL,
    "LastName"  varchar(100) NOT NULL,
    "Email"     varchar(200) NOT NULL,
    "BirthDate" date NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL
);
CREATE UNIQUE INDEX "IX_Students_Email" ON "Students" ("Email");

CREATE TABLE "Courses" (
    "Id"          integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Name"        varchar(200) NOT NULL,
    "Description" varchar(1000) NULL,
    "Credits"     integer NOT NULL,
    "TeacherId"   integer NOT NULL,
    "CreatedAt"   timestamp with time zone NOT NULL,
    CONSTRAINT "FK_Courses_Teachers_TeacherId" FOREIGN KEY ("TeacherId")
        REFERENCES "Teachers" ("Id") ON DELETE RESTRICT
);
CREATE INDEX "IX_Courses_TeacherId" ON "Courses" ("TeacherId");

CREATE TABLE "Enrollments" (
    "Id"             integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "StudentId"      integer NOT NULL,
    "CourseId"       integer NOT NULL,
    "EnrollmentDate" timestamp with time zone NOT NULL,
    "Grade"          numeric(5,2) NULL,
    CONSTRAINT "FK_Enrollments_Students_StudentId" FOREIGN KEY ("StudentId")
        REFERENCES "Students" ("Id") ON DELETE CASCADE,
    CONSTRAINT "FK_Enrollments_Courses_CourseId" FOREIGN KEY ("CourseId")
        REFERENCES "Courses" ("Id") ON DELETE RESTRICT
);
CREATE UNIQUE INDEX "IX_Enrollments_StudentId_CourseId" ON "Enrollments" ("StudentId", "CourseId");
CREATE INDEX "IX_Enrollments_CourseId" ON "Enrollments" ("CourseId");

